using System;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using Microsoft.EntityFrameworkCore.Infrastructure;
using Microsoft.EntityFrameworkCore.Migrations;
using Microsoft.Extensions.Logging;

namespace EfMigrationPack
{
    /// <summary>
    /// Base class for a packed migration generated by ef-pack. Each step runs only if its original id is
    /// absent from the history table (Up) or present in it (Down), and that id's history row is kept in sync.
    /// </summary>
    public abstract class PackedMigration : Migration
    {
        private PackedMigrationRuntime? _runtime;

        internal void Attach(PackedMigrationRuntime runtime)
        {
            _runtime = runtime;
        }

        /// <summary>Describes one step for <see cref="ApplyUp"/> or <see cref="ApplyDown"/>.</summary>
        protected static PackedStepEntry Step(string migrationId, Func<PackedStep> create)
        {
            return new PackedStepEntry(migrationId, create);
        }

        /// <summary>Applies, in the order given, every step the database has not recorded.</summary>
        protected void ApplyUp(MigrationBuilder migrationBuilder, params PackedStepEntry[] steps)
        {
            Apply(migrationBuilder, steps, up: true);
        }

        /// <summary>Reverts, in the order given, every step the database has recorded.</summary>
        protected void ApplyDown(MigrationBuilder migrationBuilder, params PackedStepEntry[] steps)
        {
            Apply(migrationBuilder, steps, up: false);
        }

        private void Apply(MigrationBuilder migrationBuilder, PackedStepEntry[] steps, bool up)
        {
            var runtime = _runtime ?? throw new InvalidOperationException(
                $"'{GetType().Name}' is a packed migration but packed migrations are not enabled. " +
                "Call UsePackedMigrations() on the DbContext options (in AddDbContext / OnConfiguring and in any IDesignTimeDbContextFactory).");

            var duplicate = steps.GroupBy(s => s.MigrationId, StringComparer.Ordinal).FirstOrDefault(g => g.Count() > 1);
            if (duplicate != null)
            {
                throw new InvalidOperationException($"Packed migration '{GetType().Name}' lists step '{duplicate.Key}' more than once.");
            }

            var packId = GetType().GetCustomAttribute<MigrationAttribute>()?.Id ?? GetType().Name;
            var applied = runtime.AppliedMigrations;
            var selected = new List<PackedStepEntry>();
            foreach (var step in steps)
            {
                // Up runs steps that are not recorded; Down reverts steps that are.
                if (applied.Contains(step.MigrationId) != up)
                {
                    selected.Add(step);
                }
                else
                {
                    runtime.Report(LogLevel.Debug, PackedMigrationEvents.StepSkipped, up
                        ? $"Skipping packed migration '{step.MigrationId}': already applied."
                        : $"Skipping packed migration '{step.MigrationId}': not applied.");
                }
            }

            runtime.Report(LogLevel.Information, PackedMigrationEvents.Summary, up
                ? $"Packed migration '{packId}': {selected.Count} of {steps.Length} migration(s) to apply, {steps.Length - selected.Count} already applied."
                : $"Packed migration '{packId}': {selected.Count} of {steps.Length} migration(s) to revert.");

            var progress = new List<PackedMigrationProgress.Item>(selected.Count);
            for (var i = 0; i < selected.Count; i++)
            {
                var entry = selected[i];
                var step = entry.Create();
                step.ActiveProvider = ActiveProvider;
                if (up)
                {
                    step.Up(migrationBuilder);
                }
                else
                {
                    step.Down(migrationBuilder);
                }

                var historyScript = up
                    ? runtime.History.GetInsertScript(new HistoryRow(entry.MigrationId, ProductInfo.GetVersion()))
                    : runtime.History.GetDeleteScript(entry.MigrationId);
                migrationBuilder.Sql(historyScript);

                // The history row is the step's last command, so it executing means the step has finished.
                progress.Add(new PackedMigrationProgress.Item(packId, entry.MigrationId, historyScript, i + 1, selected.Count, up, runtime.Report));
            }

            PackedMigrationProgress.Track(runtime.Context, packId, progress);
        }
    }
}
